<html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Kirim Aduan — LPJU & Rambu</title>@fonts @vite(['resources/css/app.css','resources/js/app.js'])</head>
<body class="min-h-screen bg-surface">
@include('components.location-marker')<main class="mx-auto max-w-4xl px-4 py-8 sm:px-6"><header class="mb-6 flex items-center justify-between gap-4"><a href="{{ route('login') }}" class="flex items-center gap-3"><span class="grid h-10 w-10 place-items-center rounded-xl bg-navy-900 text-sm font-bold text-teal-300">LR</span><span><strong class="block text-sm text-navy-900">LPJU & Rambu</strong><small class="text-xs text-slate-500">Kabupaten Kebumen</small></span></a><a href="{{ route('login') }}" class="action-link">Masuk panel</a></header>
<section x-data="complaintCreate()" x-init="init()" class="rounded-2xl border border-border bg-white p-5 shadow-sm sm:p-8"><div class="mb-6"><p class="text-xs font-semibold uppercase tracking-widest text-teal-600">Layanan masyarakat</p><h1 class="mt-2 text-2xl font-semibold tracking-tight text-navy-900">Kirim aduan aset</h1><p class="mt-2 text-sm text-slate-600">Laporkan masalah LPJU atau Rambu di Kabupaten Kebumen.</p></div>
<div x-show="success" role="status" class="mb-5 rounded-xl border border-teal-200 bg-teal-50 px-4 py-4 text-sm text-teal-800"><p class="font-semibold">Aduan berhasil diterima.</p><p class="mt-1">Nomor aduan: <strong x-text="successCode"></strong></p><button type="button" @click="resetForm()" class="mt-3 font-semibold underline">Kirim aduan lain</button></div>
