<form x-show="!success" @submit.prevent="submit" class="grid gap-5 lg:grid-cols-2" novalidate><div><label for="jenis_aset" class="field-label">Jenis aset</label><select id="jenis_aset" x-model="form.jenis_aset" @change="form.aset_id=''; selected=null" class="field-input"><option value="lpju">LPJU</option><option value="rambu">Rambu</option></select></div><div><label for="aset_id" class="field-label">Aset yang dilaporkan</label><select id="aset_id" x-model="form.aset_id" @change="selectAsset" class="field-input" required><option value="">Pilih aset</option><template x-for="asset in currentAssets" :key="asset.id"><option :value="String(asset.id)" x-text="code(asset)"></option></template></select><p x-show="fieldErrors.aset_id" class="field-error" x-text="fieldErrors.aset_id"></p></div><div><label for="kategori_aduan" class="field-label">Kategori aduan</label><select id="kategori_aduan" x-model="form.kategori_aduan" class="field-input" required><option value="">Pilih kategori</option><option value="lampu_mati">Lampu mati</option><option value="kerusakan_fisik">Kerusakan fisik</option><option value="rambu_tidak_jelas">Rambu tidak jelas</option><option value="lainnya">Lainnya</option></select></div><div><label for="nama_pelapor" class="field-label">Nama pelapor</label><input id="nama_pelapor" x-model="form.nama_pelapor" class="field-input" required></div><div><label for="kontak_pelapor" class="field-label">Nomor kontak <span class="font-normal text-slate-500">(opsional)</span></label><input id="kontak_pelapor" x-model="form.kontak_pelapor" class="field-input" type="tel"></div><div class="lg:col-span-2"><label for="alamat_kejadian" class="field-label">Alamat/lokasi kejadian</label><input id="alamat_kejadian" x-model="form.alamat_kejadian" class="field-input" required placeholder="Alamat lokasi aduan"><p x-show="fieldErrors.alamat_kejadian" class="field-error" x-text="fieldErrors.alamat_kejadian"></p></div><div class="lg:col-span-2"><div id="complaint-map" class="h-64 overflow-hidden rounded-xl bg-[#dbe7e5]"></div><p class="mt-2 text-xs text-slate-500">Pilih aset untuk melihat lokasi tersimpan pada peta.</p></div><div><label for="latitude" class="field-label">Latitude</label><input id="latitude" x-model="form.latitude" class="field-input" readonly required></div><div><label for="longitude" class="field-label">Longitude</label><input id="longitude" x-model="form.longitude" class="field-input" readonly required></div><div class="lg:col-span-2"><label for="deskripsi" class="field-label">Deskripsi aduan</label><textarea id="deskripsi" x-model="form.deskripsi" rows="4" class="w-full rounded-lg border border-border bg-white px-3 py-3 text-sm text-navy-900" required placeholder="Jelaskan kondisi yang dilaporkan"></textarea></div><div class="lg:col-span-2"><label for="foto" class="field-label">Foto pendukung <span class="font-normal text-slate-500">(opsional, maksimal 2 MB)</span></label><input id="foto" type="file" accept="image/jpeg,image/png,image/webp" @change="form.foto=$event.target.files[0]||null" class="field-input file:mr-3 file:rounded-md file:border-0 file:bg-slate-100 file:px-3 file:py-1 file:text-xs"><p x-show="fieldErrors.foto" class="field-error" x-text="fieldErrors.foto"></p></div><div class="lg:col-span-2"><button type="submit" :disabled="saving" class="action-button-primary w-full min-h-12"><span x-text="saving ? 'Mengirim aduan...' : 'Kirim aduan'"></span></button></div></form></section></main><script>function complaintCreate(){return{assets:[],selected:null,map:null,marker:null,saving:false,success:false,successCode:'',error:'',fieldErrors:{},form:{jenis_aset:'lpju',aset_id:'',kategori_aduan:'',nama_pelapor:'',kontak_pelapor:'',alamat_kejadian:'',latitude:'',longitude:'',deskripsi:'',foto:null},async init(){this.map=window.Leaflet.map('complaint-map',{center:[-7.6786,109.6565],zoom:11,scrollWheelZoom:false});window.Leaflet.tileLayer('https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,attribution:'&copy; OpenStreetMap contributors'}).addTo(this.map);await this.loadAssets();setTimeout(()=>this.map.invalidateSize(),100)},async loadAssets(){try{const res=await Promise.all([window.axios.get('/api/lpju'),window.axios.get('/api/rambu')]);this.assets=res.flatMap((r,i)=>this.normalize(r).map(a=>({...a,type:i?'rambu':'lpju'})))}catch(e){this.error='Data aset belum dapat dimuat. Silakan coba lagi.'}},normalize(r){const v=r?.data??r;return Array.isArray(v)?v:Array.isArray(v?.data)?v.data:[]},get currentAssets(){return this.assets.filter(a=>a.type===this.form.jenis_aset)},code(a){return`${a.type==='lpju'?'LPJU':'RAMBU'}-${String(a.id).padStart(4,'0')}`},selectAsset(){this.selected=this.currentAssets.find(a=>String(a.id)===String(this.form.aset_id))||null;if(!this.selected)return;this.form.alamat_kejadian=this.selected.alamat||'';this.form.latitude=this.selected.latitude||'';this.form.longitude=this.selected.longitude||'';const lat=Number(this.form.latitude),lng=Number(this.form.longitude);if(!Number.isFinite(lat)||!Number.isFinite(lng))return;if(this.marker)this.marker.setLatLng([lat,lng]);else this.marker=window.Leaflet.marker([lat,lng],{icon:window.locationMarkerIcon(),title:'Lokasi terpilih'}).addTo(this.map);this.marker.bindTooltip('Lokasi terpilih',{direction:'top'});this.map.setView([lat,lng],14)},async submit(){this.saving=true;this.error='';this.fieldErrors={};const p=new FormData();Object.entries(this.form).forEach(([k,v])=>{if(v!==null&&v!=='')p.append(k,v)});try{const r=await window.axios.post('/api/aduan',p);this.successCode=`ADUAN-${String(r.data.id).padStart(6,'0')}`;this.success=true}catch(e){this.fieldErrors=e.response?.data?.errors?Object.fromEntries(Object.entries(e.response.data.errors).map(([k,v])=>[k,v[0]])):{};this.error=e.response?.data?.message||'Aduan gagal dikirim.'}finally{this.saving=false}},resetForm(){location.reload()}}}</script></body></html>
